CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS vector;
DO $$ BEGIN CREATE TYPE review_status AS ENUM ('draft','in_review','verified','rejected','archived'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE evidence_type AS ENUM ('regulatory','clinical','preclinical_animal','in_vitro','computational','review','unknown'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS organizations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, organization_type TEXT, country_code CHAR(2), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_profiles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID REFERENCES organizations(id), external_auth_subject TEXT UNIQUE, display_name TEXT, role TEXT NOT NULL DEFAULT 'public', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS source_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), source_name TEXT NOT NULL, source_identifier TEXT, source_url TEXT, retrieved_at TIMESTAMPTZ, license_notes TEXT, raw_metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(source_name,source_identifier));
CREATE TABLE IF NOT EXISTS peptides (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), preferred_name TEXT NOT NULL, peptide_category TEXT, description TEXT, development_status TEXT, intended_use_class TEXT NOT NULL DEFAULT 'unspecified', review_status review_status NOT NULL DEFAULT 'draft', primary_source_id UUID REFERENCES source_records(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_peptides_name ON peptides USING gin(to_tsvector('english',preferred_name));
CREATE TABLE IF NOT EXISTS peptide_aliases (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), peptide_id UUID NOT NULL REFERENCES peptides(id) ON DELETE CASCADE, alias TEXT NOT NULL, source_id UUID REFERENCES source_records(id), UNIQUE(peptide_id,alias));
CREATE TABLE IF NOT EXISTS peptide_sequences (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), peptide_id UUID NOT NULL REFERENCES peptides(id) ON DELETE CASCADE, sequence TEXT NOT NULL, sequence_type TEXT NOT NULL DEFAULT 'amino_acid', n_terminus TEXT, c_terminus TEXT, modifications JSONB NOT NULL DEFAULT '[]'::jsonb, stereochemistry_notes TEXT, source_id UUID REFERENCES source_records(id), review_status review_status NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS chemical_properties (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), peptide_id UUID NOT NULL REFERENCES peptides(id) ON DELETE CASCADE, chemical_form TEXT, molecular_formula TEXT, average_molecular_mass NUMERIC(14,6), monoisotopic_mass NUMERIC(14,6), canonical_smiles TEXT, inchi TEXT, inchikey TEXT, property_origin TEXT NOT NULL DEFAULT 'unknown', method_or_tool TEXT, source_id UUID REFERENCES source_records(id), review_status review_status NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS structures (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), peptide_id UUID NOT NULL REFERENCES peptides(id) ON DELETE CASCADE, structure_type TEXT NOT NULL, file_format TEXT, storage_key TEXT, external_identifier TEXT, method_or_prediction_tool TEXT, source_id UUID REFERENCES source_records(id), review_status review_status NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS targets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), preferred_name TEXT NOT NULL, gene_symbol TEXT, organism TEXT, external_identifier TEXT, source_id UUID REFERENCES source_records(id));
CREATE TABLE IF NOT EXISTS pathways (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), preferred_name TEXT NOT NULL, database_name TEXT, external_identifier TEXT, organism TEXT, source_id UUID REFERENCES source_records(id));
CREATE TABLE IF NOT EXISTS publications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), pmid TEXT UNIQUE, doi TEXT UNIQUE, title TEXT NOT NULL, journal TEXT, publication_date DATE, abstract TEXT, url TEXT, source_id UUID REFERENCES source_records(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS research_studies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), peptide_id UUID REFERENCES peptides(id), study_title TEXT, study_design TEXT, species_or_population TEXT, model_details TEXT, sample_size INTEGER, intervention_description TEXT, comparator_description TEXT, primary_outcomes JSONB NOT NULL DEFAULT '[]'::jsonb, limitations TEXT, evidence_type evidence_type NOT NULL DEFAULT 'unknown', review_status review_status NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS study_publications (study_id UUID REFERENCES research_studies(id) ON DELETE CASCADE, publication_id UUID REFERENCES publications(id) ON DELETE CASCADE, PRIMARY KEY(study_id,publication_id));
CREATE TABLE IF NOT EXISTS evidence_claims (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), peptide_id UUID NOT NULL REFERENCES peptides(id) ON DELETE CASCADE, claim_text TEXT NOT NULL, claim_domain TEXT NOT NULL, evidence_type evidence_type NOT NULL DEFAULT 'unknown', confidence_label TEXT NOT NULL DEFAULT 'not_assessed', limitations TEXT, review_status review_status NOT NULL DEFAULT 'draft', reviewed_by UUID REFERENCES user_profiles(id), reviewed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS claim_sources (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), claim_id UUID NOT NULL REFERENCES evidence_claims(id) ON DELETE CASCADE, publication_id UUID REFERENCES publications(id), source_record_id UUID REFERENCES source_records(id), supporting_excerpt TEXT, relationship TEXT NOT NULL DEFAULT 'supports', CHECK (num_nonnulls(publication_id,source_record_id)=1));
CREATE TABLE IF NOT EXISTS peptide_target_evidence (peptide_id UUID REFERENCES peptides(id) ON DELETE CASCADE, target_id UUID REFERENCES targets(id) ON DELETE CASCADE, interaction_description TEXT, evidence_type evidence_type NOT NULL DEFAULT 'unknown', source_id UUID REFERENCES source_records(id), review_status review_status NOT NULL DEFAULT 'draft', PRIMARY KEY(peptide_id,target_id,evidence_type));
CREATE TABLE IF NOT EXISTS peptide_pathway_evidence (peptide_id UUID REFERENCES peptides(id) ON DELETE CASCADE, pathway_id UUID REFERENCES pathways(id) ON DELETE CASCADE, evidence_description TEXT, evidence_type evidence_type NOT NULL DEFAULT 'unknown', source_id UUID REFERENCES source_records(id), review_status review_status NOT NULL DEFAULT 'draft', PRIMARY KEY(peptide_id,pathway_id,evidence_type));
CREATE TABLE IF NOT EXISTS analytical_methods (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), method_name TEXT NOT NULL, method_category TEXT NOT NULL, scientific_principle TEXT, intended_purpose TEXT, applicable_materials TEXT[], method_classification TEXT, reference_standard TEXT, validation_status TEXT NOT NULL DEFAULT 'not_assessed', acceptance_criteria_source TEXT, limitations TEXT, source_id UUID REFERENCES source_records(id), review_status review_status NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS vendors (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), legal_name TEXT NOT NULL, website_url TEXT, country_code CHAR(2), vendor_type TEXT NOT NULL, verification_status TEXT NOT NULL DEFAULT 'unverified', last_verified_at TIMESTAMPTZ, verification_notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vendor_sites (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), vendor_id UUID NOT NULL REFERENCES vendors(id) ON DELETE CASCADE, site_name TEXT, address TEXT, country_code CHAR(2), site_scope TEXT);
CREATE TABLE IF NOT EXISTS vendor_services (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), vendor_id UUID NOT NULL REFERENCES vendors(id) ON DELETE CASCADE, service_name TEXT NOT NULL, capability_description TEXT, evidence_source_id UUID REFERENCES source_records(id), verified_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS vendor_certifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), vendor_id UUID NOT NULL REFERENCES vendors(id) ON DELETE CASCADE, site_id UUID REFERENCES vendor_sites(id), certification_name TEXT NOT NULL, issuing_body TEXT, certificate_reference TEXT, scope TEXT, valid_from DATE, valid_until DATE, verification_source_id UUID REFERENCES source_records(id), verification_status TEXT NOT NULL DEFAULT 'unverified');
CREATE TABLE IF NOT EXISTS regulatory_status (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), peptide_id UUID NOT NULL REFERENCES peptides(id) ON DELETE CASCADE, jurisdiction TEXT NOT NULL, authority TEXT, status TEXT NOT NULL, indication_or_scope TEXT, effective_date DATE, source_id UUID REFERENCES source_records(id), review_status review_status NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS audit_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id UUID REFERENCES user_profiles(id), organization_id UUID REFERENCES organizations(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id UUID, event_metadata JSONB NOT NULL DEFAULT '{}'::jsonb, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_claims_peptide ON evidence_claims(peptide_id);
CREATE INDEX IF NOT EXISTS idx_methods_category ON analytical_methods(method_category);
CREATE INDEX IF NOT EXISTS idx_vendors_country ON vendors(country_code);
